import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { Children, type ReactNode } from "react";
import { tv, type VariantProps } from "tailwind-variants";

export function buttonLabel(children: ReactNode): ReactNode {
  const parts: ReactNode[] = [];
  let text = "";
  const flush = () => {
    if (text.trim()) {
      parts.push(
        <span
          key={`label-${parts.length}`}
          data-slot="button-label"
          className="min-w-0 truncate"
        >
          {text}
        </span>,
      );
    }
    text = "";
  };
  for (const child of Children.toArray(children)) {
    if (typeof child === "string" || typeof child === "number") {
      text += child;
    } else {
      flush();
      parts.push(child);
    }
  }
  flush();
  return parts;
}

export const touchTarget =
  "relative pointer-coarse:after:absolute pointer-coarse:after:inset-x-0 pointer-coarse:after:top-1/2 pointer-coarse:after:h-[max(100%,var(--touch-target,2.75rem))] pointer-coarse:after:-translate-y-1/2";

export const buttonStyles = tv({
  base: "inline-flex min-w-0 max-w-full shrink-0 cursor-default items-center justify-center whitespace-nowrap rounded-md font-medium tracking-[-0.01em] outline-offset-4 outline-transparent transition-[color,background-color,border-color,box-shadow,scale,outline-color,outline-offset] duration-150 ease-out-quint disabled:cursor-default disabled:opacity-50 disabled:shadow-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:outline-offset-2 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 pressed:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 pressed:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted",
      ghost:
        "text-foreground hover:bg-muted pressed:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 pressed:bg-destructive/90",
    },
    size: {
      xs: `h-7 gap-1.5 rounded-sm px-2.5 text-xs [&_svg:not([class*='size-'])]:size-3.5 ${touchTarget}`,
      sm: `h-9 gap-2 px-3.5 text-sm [&_svg:not([class*='size-'])]:size-4 ${touchTarget}`,
      md: "h-11 gap-2 px-5 text-sm [&_svg:not([class*='size-'])]:size-4",
      lg: "h-12 gap-2 px-6 text-sm [&_svg:not([class*='size-'])]:size-4",
      xl: "h-14 gap-2.5 rounded-lg px-7 text-base [&_svg:not([class*='size-'])]:size-5",
    },
    iconOnly: {
      true: "cursor-pointer px-0",
    },
  },
  compoundVariants: [
    { size: "xs", iconOnly: true, class: "w-7" },
    { size: "sm", iconOnly: true, class: "w-9" },
    {
      size: "md",
      iconOnly: true,
      class: "w-11 [&_svg:not([class*='size-'])]:size-4.5",
    },
    {
      size: "lg",
      iconOnly: true,
      class: "w-12 [&_svg:not([class*='size-'])]:size-5",
    },
    {
      size: "xl",
      iconOnly: true,
      class: "w-14 [&_svg:not([class*='size-'])]:size-6",
    },
  ],
  defaultVariants: { variant: "default", size: "md" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import { type ButtonVariant, buttonLabel, buttonStyles } from "./button-styles";
import { type Size, useSize } from "./size";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: Size;
  iconOnly?: boolean;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  children,
  variant = "default",
  size: sizeProp,
  iconOnly = false,
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  const size = useSize(sizeProp) ?? "md";
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          iconOnly,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    >
      {composeRenderProps(children, buttonLabel)}
    </MotionButton>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  ProgressBar as AriaProgressBar,
  type ProgressBarProps as AriaProgressBarProps,
  composeRenderProps,
  Label,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export interface ProgressBarProps
  extends Omit<AriaProgressBarProps, "className" | "children"> {
  label?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaProgressBarProps["className"];
  children?: AriaProgressBarProps["children"];
}

export function ProgressBar({
  label,
  className,
  children,
  ...props
}: ProgressBarProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaProgressBar
      {...props}
      data-slot="progress-bar"
      className={composeRenderProps(className, (className) =>
        cn("grid w-full gap-2", className),
      )}
    >
      {children ??
        (({ percentage, valueText, isIndeterminate }) => (
          <>
            {(label || !isIndeterminate) && (
              <div className="flex items-baseline gap-3 text-sm">
                {label && (
                  <Label
                    data-slot="progress-bar-label"
                    className="min-w-0 flex-1 font-medium text-foreground [overflow-wrap:anywhere]"
                  >
                    {label}
                  </Label>
                )}
                {!isIndeterminate && (
                  <span
                    data-slot="progress-bar-value"
                    className="ms-auto max-w-1/2 shrink-0 text-end font-mono tabular-nums text-muted-foreground [overflow-wrap:anywhere]"
                  >
                    {valueText}
                  </span>
                )}
              </div>
            )}
            <div
              data-slot="progress-bar-track"
              className="h-2 overflow-hidden rounded-full bg-secondary shadow-[var(--shadow-inset)] forced-colors:border rtl:-scale-x-100"
            >
              {isIndeterminate ? (
                <motion.div
                  key="indeterminate"
                  data-slot="progress-bar-fill"
                  className="h-full w-1/3 rounded-full bg-primary forced-colors:bg-[Highlight]"
                  initial={false}
                  animate={{ x: reduceMotion ? "100%" : ["-100%", "300%"] }}
                  transition={
                    reduceMotion
                      ? { duration: 0 }
                      : { duration: 1.6, repeat: Infinity, ease: "linear" }
                  }
                />
              ) : (
                <motion.div
                  key="determinate"
                  data-slot="progress-bar-fill"
                  className="h-full w-full origin-left rounded-full bg-primary forced-colors:bg-[Highlight]"
                  initial={false}
                  animate={{ scaleX: (percentage ?? 0) / 100 }}
                  transition={{
                    duration: reduceMotion ? 0 : duration.base,
                    ease: easeOut,
                  }}
                />
              )}
            </div>
          </>
        ))}
    </AriaProgressBar>
  );
}

"use client";

import {
  FileCodeIcon,
  FileImageIcon,
  FilePdfIcon,
  FileTextIcon,
  FileZipIcon,
  WarningIcon,
  XIcon,
} from "@phosphor-icons/react";
import {
  AnimatePresence,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import type { ComponentProps, ReactNode } from "react";
import { duration, easeOut, springLayout, transitionFor } from "./motion";
import { cn } from "./utils";
import { Button } from "./button";
import { ProgressBar } from "./progress-bar";

export interface AttachmentListProps extends ComponentProps<"ul"> {
  children: ReactNode;
}

export function AttachmentList({
  children,
  className,
  ...props
}: AttachmentListProps) {
  return (
    <ul
      {...props}
      data-slot="attachment-list"
      aria-label={props["aria-label"] ?? "Attachments"}
      className={cn("grid min-w-0 gap-2", className)}
    >
      <AnimatePresence initial={false}>{children}</AnimatePresence>
    </ul>
  );
}

export interface AttachmentProps
  extends Omit<
    ComponentProps<"li">,
    | "children"
    | "onDrag"
    | "onDragStart"
    | "onDragEnd"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
  > {
  name: string;
  size?: number;
  previewUrl?: string;
  status?: "ready" | "uploading" | "uploaded" | "error";
  progress?: number;
  errorMessage?: string;
  onRemove?: () => void;
  onRetry?: () => void;
}

const sizeUnits = ["B", "KB", "MB", "GB", "TB"];

function formatSize(bytes: number) {
  let value = Math.max(0, bytes);
  let unit = 0;
  while (unit < sizeUnits.length - 1 && Number(value.toFixed(1)) >= 1024) {
    value /= 1024;
    unit += 1;
  }
  const amount = unit === 0 ? Math.round(value) : Number(value.toFixed(1));
  return `${amount} ${sizeUnits[unit]}`;
}

export function Attachment({
  name,
  size,
  previewUrl,
  status = "ready",
  progress,
  errorMessage,
  onRemove,
  onRetry,
  className,
  ...props
}: AttachmentProps) {
  const reduceMotion = useReducedMotion() === true;
  const isPresent = useIsPresent();
  const extension = name.split(".").pop()?.toLowerCase();
  const FileIcon =
    extension === "pdf"
      ? FilePdfIcon
      : extension === "zip"
        ? FileZipIcon
        : ["png", "jpg", "jpeg", "gif", "webp", "svg"].includes(extension ?? "")
          ? FileImageIcon
          : ["js", "jsx", "ts", "tsx", "json", "html", "css"].includes(
                extension ?? "",
              )
            ? FileCodeIcon
            : FileTextIcon;
  const statusText =
    status === "uploading"
      ? "Uploading"
      : status === "uploaded"
        ? "Uploaded"
        : status === "error"
          ? (errorMessage ?? "Could not upload")
          : "Ready";

  return (
    <motion.li
      {...props}
      data-slot="attachment"
      data-status={status}
      inert={!isPresent}
      aria-hidden={!isPresent || undefined}
      layout={reduceMotion ? false : "position"}
      initial={reduceMotion ? false : { opacity: 0, y: 6 }}
      animate={{ opacity: 1, y: 0 }}
      exit={reduceMotion ? { opacity: 1 } : { opacity: 0, y: -6 }}
      transition={transitionFor(reduceMotion, {
        duration: duration.base,
        ease: easeOut,
        layout: springLayout,
      })}
      className={cn(
        "flex min-w-0 items-center gap-3 rounded-lg border border-border bg-card p-2 text-sm shadow-[var(--shadow-card)]",
        status === "error" && "border-destructive/60",
        className,
      )}
    >
      <span
        aria-hidden="true"
        data-slot="attachment-preview"
        className="flex size-11 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted text-muted-foreground"
      >
        {previewUrl ? (
          // biome-ignore lint/performance/noImgElement: Files can be object URLs in any React app.
          <img src={previewUrl} alt="" className="size-full object-cover" />
        ) : (
          <FileIcon size={20} aria-hidden="true" />
        )}
      </span>
      <div className="flex min-w-0 flex-1 flex-wrap items-center gap-x-3">
        <div className="min-w-[min(8rem,100%)] flex-1">
          <p
            data-slot="attachment-name"
            className="font-medium text-foreground [overflow-wrap:anywhere]"
          >
            {name}
          </p>
          <p
            data-slot="attachment-details"
            className={cn(
              "text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]",
              status === "error" && "text-destructive",
            )}
          >
            {status === "error" && (
              <WarningIcon
                size={13}
                weight="bold"
                aria-hidden="true"
                className="me-1 inline-block align-[-2px]"
              />
            )}
            {size !== undefined && (
              <>
                <span>{formatSize(size)}</span>
                <span aria-hidden="true"> · </span>
              </>
            )}
            <span>{statusText}</span>
          </p>
          {status === "uploading" && (
            <ProgressBar
              aria-label={`${name} upload`}
              value={progress ?? 0}
              isIndeterminate={progress === undefined}
              className="mt-2"
            />
          )}
        </div>
        {status === "error" && onRetry && (
          <Button type="button" variant="ghost" size="sm" onPress={onRetry}>
            Retry
          </Button>
        )}
      </div>
      {onRemove && (
        <Button
          type="button"
          variant="ghost"
          iconOnly
          aria-label={`Remove ${name}`}
          onPress={onRemove}
        >
          <XIcon aria-hidden="true" />
        </Button>
      )}
    </motion.li>
  );
}

